package cloudflare

import (
	"bytes"
	"errors"
	"fmt"
	"net"
	"net/http"
	"net/http/httputil"
	"time"

	"golang.org/x/net/context"

	"google.golang.org/appengine"
	"google.golang.org/appengine/socket"
	"hanzo.io/config"
	"hanzo.io/util/json"
	"hanzo.io/util/log"
)

type Client struct {
	Email    string
	Key      string
	Endpoint string

	ctx    context.Context
	client *http.Client
}

func New(ctx context.Context) *Client {
	ctx, _ = context.WithTimeout(ctx, 20*time.Second)
	client := &http.Client{
		Transport: &http.Transport{
			Dial: func(network, addr string) (net.Conn, error) {
				return socket.Dial(ctx, network, addr)
			},
		},
	}

	return &Client{
		ctx:      ctx,
		client:   client,
		Email:    config.Cloudflare.Email,
		Key:      config.Cloudflare.Key,
		Endpoint: "https://api.cloudflare.com/client/v4",
	}
}

func (c *Client) Request(method, url string, data interface{}) (*http.Response, error) {
	var payload *bytes.Buffer

	if data != nil {
		payload = json.EncodeBuffer(data)
	}

	req, err := http.NewRequest(method, c.Endpoint+url, payload)
	if err != nil {
		return nil, err
	}

	req.Header.Add("X-Auth-Email", c.Email)
	req.Header.Add("X-Auth-Key", c.Key)
	req.Header.Add("Content-Type", "application/json")

	body, _ := httputil.DumpRequestOut(req, true)
	log.Warn("Cloudflare Request: %#v\n%s", req, string(body), c.ctx)

	res, err := c.client.Do(req)
	if err != nil {
		log.Warn("Cloudflare error on request: %v", err)
	} else {
		// according to https://golang.org/pkg/net/http/#Client.Do
		// the body only needs to be closed when (err == nil)
		defer res.Body.Close()
		body, _ = httputil.DumpResponse(res, true)
		log.Warn("Cloudflare Response: %#v\n%s", res, string(body), c.ctx)
	}
	return res, err
}

type PurgeRequest struct {
	Files []string `json:"files"`
}

// zone is an id generated by cloudflare
// use config.Cloudflare.ZoneId
func (c *Client) Purge(zone string, files []string) error {
	// Cloudflare zone only exists for staging and production
	if appengine.IsDevAppServer() {
		return nil
	}

	req := &PurgeRequest{Files: files}

	res, err := c.Request("DELETE", "/zones/"+zone+"/purge_cache", req)
	if err != nil {
		return err
	}

	if res.StatusCode >= 300 {
		return errors.New(fmt.Sprintf("Failed to purge cache: %s", res.Status))
	}

	return err
}

func Purge(ctx context.Context, url string) error {
	client := New(ctx)
	files := []string{
		"http:" + url,
	}

	return client.Purge(config.Cloudflare.ZoneId, files)
}
